	'upd_req_writable_help' => "O PHP corre como «%1\$s» e só pode ler estas pastas: pertencem ao utilizador que as carregou (p. ex. por SFTP), com as permissões habituais 755 (outros: só leitura).\nCorrigir por SSH (pasta: %2\$s):\n• sudo chown -R %1\$s %2\$s – os ficheiros pertencem ao PHP (por SFTP depois só legíveis)\n• ou partilhado: sudo chown -R oseuuser:%1\$s %2\$s e chmod 2775 nas pastas, 664 nos ficheiros\nSem SSH, no cliente SFTP (p. ex. FileZilla: clique direito → Permissões do ficheiro): definir as pastas para 777 (ler, escrever, executar para todos – «executar» numa pasta significa «pode entrar»), recursivo, só pastas. Instalar a atualização e voltar a 755.\nOu atualizar à mão: carregar os ficheiros de nunext.zip por cima dos antigos.",
