	'rd_help' => 'Ajuda',
	'rd_help_text' => 'Arraste campos da esquerda para uma secção, ou clique em Campo / Texto / Retângulo / Linha / Imagem. As secções imprimem nesta ordem: cabeçalho do relatório (uma vez), cabeçalho da página (cada página), cabeçalhos de grupo, detalhe (cada linha), rodapés de grupo, rodapé da página, rodapé do relatório.\\nMova os objetos com o rato (também para outra secção) ou com as setas (Shift = 4 mm, Alt = 0,25 mm); as pegas mudam o tamanho. Shift-clique ou uma moldura para selecionar vários, depois os botões de alinhar.\\nCtrl+Z / Ctrl+Y anular e refazer, Ctrl+C / Ctrl+V copiar, Ctrl+D duplica, Del elimina, Ctrl+S guarda.\\nCampos: uma coluna, SUM(coluna) ou AVERAGE(a, b) – somas por grupo de ordenação. Os textos podem conter #page#, #pages#, #code#, #description#, #nu_date# e qualquer variável hash (p. ex. campos do formulário de início).\\nUm valor que começa por #B#rrggbb| ou #F#rrggbb| recebe essa cor de fundo / texto (formatação condicional a partir da fonte de dados).\\nA pré-visualização imprime o layout atual com critérios vazios; o layout é guardado no formato do nuBuilder.',
