	'secchk_settings' => 'Definições de segurança',
	'secchk_set_rights_globeadmin_only' => 'Só o globeadmin concede direitos de administração',
	'secchk_set_rights_globeadmin_only_tip' => 'Os direitos de guardar, adicionar, novo, eliminar e clonar no construtor de formulários, procedimentos, construtor SQL, configuração, utilizadores e níveis de acesso dão controlo total (código no servidor, direitos próprios). Ativo: só o globeadmin os concede ou atribui níveis de acesso que os têm; mais ninguém altera esses utilizadores; ninguém altera o seu próprio nível de acesso nem os seus direitos; os outros não podem guardar estes formulários de sistema através dos formulários.',
	'secchk_set_protect_fields' => 'Não guardar a partir do navegador os campos só de leitura e ocultos',
	'secchk_set_protect_fields_tip' => 'Os campos com acesso «só de leitura» ou «oculto» mantêm o valor guardado, seja o que for que o navegador envie. Desativado = como o nuBuilder: o JavaScript que preenche esses campos (p. ex. nuSetValue num campo oculto) continua a funcionar.',
	'secchk_set_record_check' => 'Registos apenas através da lista do formulário',
	'secchk_set_record_check_tip' => 'Um registo só pode ser aberto, guardado ou eliminado se o SQL de lista do formulário (com as variáveis hash do utilizador) o encontrar. Formulários sem SQL de lista e SQL que precisa de código Before Browse não são verificados. Desativado = como o nuBuilder.',
	'secchk_set_field_access_ga' => 'Aplicar as regras de acesso aos dados ao globeadmin',
	'secchk_set_field_access_ga_tip' => 'Para testes: as regras de acesso a campos e colunas aplicam-se também ao globeadmin. Desligado = o globeadmin vê tudo com o acesso do nuBuilder.',
	'secchk_set_md5_login' => 'Aceitar palavras-passe md5 antigas',
	'secchk_set_md5_login_tip' => 'As palavras-passe do nuBuilder anteriores à 4.5 são hashes md5; no início de sessão passam a bcrypt. Desativado: esses utilizadores têm de definir uma nova palavra-passe («Esqueci a palavra-passe» ou o administrador).',
	'secchk_set_log_keep_days' => 'Manter o registo (dias)',
	'secchk_set_log_keep_days_tip' => 'As entradas mais antigas do registo do nuBuilder Next são eliminadas pela manutenção (cron.php, ou de vez em quando uma visita a uma página). 0 = manter tudo.',
	'secchk_set_reauth_minutes' => 'Voltar a pedir a palavra-passe após (minutos)',
	'secchk_set_reauth_minutes_tip' => 'A atualização, as cópias de segurança, nuconfig.php, as definições, o clonador de aplicações, os clientes API, phpMyAdmin / o gestor de ficheiros, «Agir como utilizador» com acesso total e estas definições pedem a palavra-passe se o início de sessão ou a última confirmação for mais antigo. 0 = nunca pedir.',
	'secchk_set_reauth_minutes_dev' => 'Pedir novamente a palavra-passe em modo de programador após (minutos)',
	'secchk_set_reauth_minutes_dev_tip' => 'Apenas para o globeadmin com $nuConfigDevMode = true: o desenvolvimento é feito sem dados reais, por isso a confirmação da palavra-passe dura mais (predefinição 480 = 8 horas). 0 = nunca pedir. Sem modo de programador aplica-se a definição acima.',
	'secchk_set_login_token' => 'Aceitar os tokens de início de sessão de utilização única do nuBuilder',
	'secchk_set_login_token_tip' => 'As ligações index.php?u=<nome de início de sessão ou id>&p=<token> iniciam a sessão de um utilizador uma vez quando o token corresponde a LOGIN_TOKEN em sus_json («Single-User Password Token» do nuBuilder; sem segundo fator, como no nuBuilder). Nunca o globeadmin. Desligado, estas ligações abrem a página de início de sessão.',
	'secchk_set_form_drafts_required' => 'Alterar formulários publicados apenas através de rascunhos',
	'secchk_set_form_drafts_required_tip' => 'O editor de formulários edita um rascunho; os utilizadores veem a alteração depois de publicada. O globeadmin pode ainda alterar um formulário em produção após confirmação.',
	'secchk_set_form_preview_saves' => 'Novos rascunhos: permitir guardar na pré-visualização',
	'secchk_set_form_preview_saves_tip' => 'Guardar e Eliminar numa pré-visualização de rascunho alteram os dados reais. Desligado: a pré-visualização é só de leitura.',
	'secchk_probe_title' => 'Ficheiros na web',
	'secchk_probe_tip' => 'Este navegador pede ficheiros do nuBuilder Next que o servidor web nunca deve servir (notas, scripts de instalação, cópias de segurança, código). O Apache usa os ficheiros .htaccess do pacote; o nginx precisa de regras próprias.',
